import { describe, expect, it } from "vitest";
import { isValidRib, normalizeRib } from "./rib";

// Generated by the backend (Rib.generate) during a smoke test
const VALID = "EB3094712094552729193874";

describe("rib", () => {
  it("accepts a backend-generated RIB, ignoring spaces and case", () => {
    expect(isValidRib(VALID)).toBe(true);
    expect(isValidRib(" eb30 9471 2094 5527 2919 3874 ")).toBe(true);
    expect(normalizeRib(" eb30 9471 ")).toBe("EB309471");
  });

  it("detects a single mistyped digit", () => {
    expect(isValidRib(VALID.slice(0, -1) + "5")).toBe(false);
  });

  it("rejects other formats", () => {
    expect(isValidRib("")).toBe(false);
    expect(isValidRib("FR7630006000011234567890189")).toBe(false);
    expect(isValidRib("EB30947120945527291938")).toBe(false);
  });
});
